    "overview": "Что произойдет, если том могущественных заклинаний обретет разум? Вы получите не менее могущественного Фолио. Возможно, он предпочитает тишину библиотеки хаосу битвы, но ненасытное любопытство заставило его примкнуть к рядам Стражей. И теперь, когда мир наблюдает за тем, как его тайные силы раскрываются на поле боя, никто больше не назовет его маленьким. За его страницами скрывается мудрость веков, готовая обрушиться на тех, кто его недооценивает. Фолио — это не просто книга заклинаний, он и есть сама книга заклинаний. Разумный гримуар, вышедший из архивов самой магии, Фолио превосходит все ожидания своим интеллектом и силой. Вовлеченный в конфликт Доминиона не долгом, а чистым любопытством, он приносит с собой многовековое магическое понимание и острый ум, который ставит врагов в тупик еще до того, как будет произнесено первое заклинание.",
