    "conclusion": "Фолио — мощный маг задней линии, который превосходно наносит высокий магический урон и ослабляет защиту противников. Его набор умений делает его особенно эффективным против команд, лишенных сильной магической защиты, а синергия с такими героями, как Орион, Небула и Амира, увеличивает его взрывной потенциал как в атаке, так и в обороне. Однако его низкая броня и здоровье делают позиционирование и защиту жизненно важными — сочетание его с героями, предлагающими щиты, исцеление или энергетическую поддержку, является ключом к максимизации его воздействия. При правильной сборке и размещении в подходящих составах команд Фолио становится смертоносной силой, способной переломить ход битвы в Hero Wars: Dominion Era."
