    "conclusion": "Джет — это универсальный и мощный герой поддержки задней линии, который отлично справляется с лечением, усилением физических союзников и ослаблением вражеской защиты. Его навыки в сочетании с правильными героями, питомцами и артефактами могут переломить ход битвы, максимизируя выживаемость команды и потенциал критического урона. Освоение Джета означает понимание его синергии, эффективное распределение времени использования его способностей и выбор лучших компаньонов и военных флагов для усиления его влияния. При правильной настройке Джет остается незаменимым героем поддержки как в PvE, так и в PvP сценариях."
