    "overview": "Кайла, свирепый Вестник Огня, проносится по полю боя с непревзойденной яростью и решимостью. Разрываясь между своим наследием пепельных эльфов и демонической родословной, она направляет свой гнев в неостановимые атаки, которые прожигают даже самую прочную оборону. Кайла сражается бок о бок со своим братом Айданом, чтобы вернуть свет и надежду в Доминион. Будь то уничтожение героев поддержки задней линии, таких как Себастьян, или принятие ударов на передовой, огненное присутствие Кайлы способно переломить ход любого сражения. Она является бойцом первой линии, который специализируется на разрушении вражеского строя и быстром устранении ключевых целей.",
