    "overview": "Маши и Грибочек — один из самых уникальных танков в Hero Wars: Dominion Era, рожденный древней магией леса. Будучи разумными грибами, развившимися благодаря чистой лесной энергии, они сражаются не как один герой, а как целое множество. Их игровой процесс строится вокруг создания дополнительных копий, которые вступают в бой после получения достаточного количества исцеления. Это открывает уникальную стратегию, вознаграждающую команды с упором на выживаемость и постоянное лечение. Их синергия с такими целителями, как Марта, Эйдан и Майя, позволяет им многократно увеличивать свое присутствие на передовой, а способность накладывать молчание помогает нейтрализовать опасных магов. Они одновременно очаровательны и сильны, что делает их фаворитами среди игроков, предпочитающих творческие и тактические сборки команд.",
