    "overview": "Сорвиголова — это мощный стрелок на задней линии, специализирующийся на нанесении огромного физического урона по площади и одиночным целям. Ее уникальная механика завязана на взаимодействии с союзниками: она совершает дополнительные выстрелы каждый раз, когда атакуют союзники, стоящие позади нее. Это делает ее невероятно опасным союзником в быстрых физических пачках, способных за секунды разрывать переднюю линию противника. Однако, как и любой классический стрелок, она обладает низким запасом здоровья и требует надежной защиты.",
